# Indexed catalogue schema, retained for migration and query tests.
SCHEMA='\nCREATE TABLE meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);\nCREATE TABLE areas(banc TEXT PRIMARY KEY);\nCREATE TABLE actors(id TEXT PRIMARY KEY,label TEXT,search TEXT,family INTEGER,logic TEXT,\n class_name TEXT,tier TEXT,closest INTEGER,reported INTEGER,placement_count INTEGER,\n physics TEXT,source TEXT,sha256 TEXT);\nCREATE TABLE placements(id INTEGER PRIMARY KEY,actor TEXT NOT NULL REFERENCES actors(id),\n actor_hash TEXT NOT NULL,banc TEXT NOT NULL,x REAL,y REAL,z REAL,yaw REAL NOT NULL,\n has_position INTEGER NOT NULL,known_area INTEGER NOT NULL,map_age TEXT NOT NULL,\n spawn_age TEXT NOT NULL,presence TEXT,dynamic TEXT,source TEXT,source_sha256 TEXT,\n UNIQUE(source,actor_hash));\nCREATE INDEX placements_actor_area ON placements(actor,banc,map_age,spawn_age);\nCREATE INDEX placements_area_age ON placements(banc,map_age,spawn_age,actor);\n'
